import { readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';

const pkg = resolve('extensions/sdk-ts/node_modules/@earendil-works/pi-coding-agent');
if (JSON.parse(readFileSync(join(pkg, 'package.json'), 'utf8')).version !== '1.0.0') throw Error('unexpected Pi version');
const core = (name) => import(pathToFileURL(join(pkg, `dist/core/${name}.js`)));
const { createExtensionRuntime } = await core('extensions/loader');
const { ExtensionRunner } = await core('extensions/runner');
const { ModelRuntime } = await core('model-runtime');
const { ModelRegistry } = await core('model-registry');
const { AuthStorage } = await core('auth-storage');
const { SessionManager } = await core('session-manager');
const modelRuntime = await ModelRuntime.create({credentials: AuthStorage.inMemory(), modelsPath: null, allowModelNetwork: false});
const registry = new ModelRegistry(modelRuntime);
const actions = {sendMessage(){},sendUserMessage(){},appendEntry(){},setSessionName(){},getSessionName(){},setLabel(){},getActiveTools:()=>[],getAllTools:()=>[],setActiveTools(){},refreshTools(){},getCommands:()=>[],setModel:async()=>false,getThinkingLevel:()=> 'off',setThinkingLevel(){}};
const contexts = {getModel(){},isIdle:()=>true,isProjectTrusted:()=>true,getSignal(){},abort(){},hasPendingMessages:()=>false,shutdown(){},getContextUsage(){},compact(){},getSystemPrompt:()=>'',getScopedModels:()=>[]};
const providerModelConfig = JSON.parse(readFileSync('test/parity/scenarios/extensions-runtime/testdata/runner-providers/config.json', 'utf8'));
const runtime = createExtensionRuntime();
runtime.registerProvider('broken-provider', {streamSimple(){throw Error('should not run');}}, '/tmp/broken-extension.ts');
const runner = new ExtensionRunner([], runtime, process.cwd(), SessionManager.inMemory(), registry);
const errors = [];
runner.onError(error => errors.push(`${error.extensionPath}: ${error.error}`));
runner.bindCore(actions, contexts);
console.log(JSON.stringify({errors, aborted:(await registry.refresh()).aborted}));
const queued = createExtensionRuntime();
queued.registerProvider('queued-provider', providerModelConfig);
queued.registerProvider('queued-provider', {...providerModelConfig, models:[{id:'instant-model-2',name:'Instant Model 2',reasoning:false,input:['text'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:128000,maxTokens:4096}]});
const before = queued.pendingProviderRegistrations.length;
queued.unregisterProvider('queued-provider');
console.log(JSON.stringify({before, after:queued.pendingProviderRegistrations.length}));
const live = createExtensionRuntime();
new ExtensionRunner([], live, process.cwd(), SessionManager.inMemory(), registry).bindCore(actions,contexts);
const pendingBefore = live.pendingProviderRegistrations.length;
live.registerProvider('instant-provider', providerModelConfig);
console.log(JSON.stringify({pendingBefore,pendingAfter:live.pendingProviderRegistrations.length,tiers:registry.find('instant-provider','instant-model')?.cost.tiers}));
live.unregisterProvider('instant-provider');
console.log(JSON.stringify({removed:registry.find('instant-provider','instant-model') === undefined}));
runtime.invalidate();
queued.invalidate();
live.invalidate();
